-- Together Plants: source-verified catalog, original identity and four-stamp loyalty
-- Apply only after 20261031235252_gift_commerce_orders_and_finance
BEGIN;
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SET LOCAL lock_timeout='5s';
SELECT id FROM public.cafes WHERE id='4e5a661a-7029-40ec-a3bc-dc75959a05bb' FOR UPDATE;
CREATE TEMP TABLE together_before AS SELECT jsonb_build_object('cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafes t WHERE id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.menu_products t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.menu_categories t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafe_loyalty_programs t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafe_custom_identity t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafe_settings t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.subscriptions t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.brand_feature_overrides t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'store_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.gift_store_settings t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'plans',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM public.platform_plans t)) AS snapshot;
DO $guard$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='4e5a661a-7029-40ec-a3bc-dc75959a05bb' AND slug='brand-871ec6e243c0' AND business_category='cafes_coffee' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Together brand identity changed';END IF;
IF EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb') OR EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb') OR EXISTS(SELECT 1 FROM public.cafe_loyalty_programs WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb') OR EXISTS(SELECT 1 FROM public.gift_orders WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb') THEN RAISE EXCEPTION 'Together is already configured; inspect before changing data';END IF;
END $guard$;
UPDATE public.cafes SET business_category='gifts_flowers',updated_at=now() WHERE id='4e5a661a-7029-40ec-a3bc-dc75959a05bb';
