INSERT INTO public.menu_products(id,cafe_id,category_id,name,description,price,catalog_kind,commerce_details,sort_order,available,image_storage_path,image_gallery,media,available_for_pickup) VALUES('e2f728f2-5fa5-452c-881d-9488e9b2cc3f','4e5a661a-7029-40ec-a3bc-dc75959a05bb','381a444b-ac0e-477e-8076-0ce9e45f922b','نبتة الزاميا','يعتبر نبات ZZ نباتًا معماريًا ملفتًا للنظر بأوراق شمعية ذات لون أخضر داكن وبيضاوية الشكل متصلة بسيقانها المقوسة الأنيقة. إنه نبات سهل العناية، فهو يتحمل الجفاف ويمكنه التأقلم بشكل جيد في مجموعة من ظروف الإضاءة بما في ذلك الظل الخفيف. أحد أكثر النباتات شعبية لدينا، ويمكن أيضًا أن يكون سريع النمو، لذا فهو طريقة رائعة منخفضة الضغط للحصول على نبات عالي التأثير في منزلك. يعمل بشكل جيد في غرف النوم والمطابخ وغرف المعيشة',56.35,'product','{"sourceUrl":"https://xeoufj.zid.store/products/نبته-الزاميا","quoteOnly":false,"stock":9,"attributes":[{"label":"رمز المنتج","value":"Z.472517.1703158692992979"},{"label":"السعر قبل التخفيض","value":"78.20 ريال"}],"optionGroups":[{"id":"da99a3b1-8710-4831-9d8b-09d4c6b79892","label":"حجم النبتة🌱","type":"select","required":false,"hint":"","minChoices":0,"maxChoices":1,"choices":[{"id":"01979afa-ac46-4eb6-ba11-7862891e1d46","label":"كبيرة🪴","priceDelta":95}]},{"id":"38a02ec8-4798-4238-a624-4d33b30c52e0","label":"اختار الأصيص المناسب لك🪴","type":"multi","required":true,"hint":"","minChoices":1,"maxChoices":3,"choices":[{"id":"02af36b6-c928-4d61-9ffb-77584b7d916c","label":"أصيص بلاستك","priceDelta":0},{"id":"new-1728216691849","label":"أصيص زجاجي","priceDelta":20},{"id":"new-1764236025688","label":"أصيص سيراميك","priceDelta":30}]}]}'::jsonb,5,true,'4e5a661a-7029-40ec-a3bc-dc75959a05bb/e2f728f2-5fa5-452c-881d-9488e9b2cc3f/together-20261101-6093917c-fe86-4521-baf2-4c86a7bd305e-403061c343c6.webp','[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/e2f728f2-5fa5-452c-881d-9488e9b2cc3f/together-20261101-f0e94c42-0085-4261-b566-9d9219978fee-7a2ae698d94f.webp","alt":"نبتة الزاميا"}]'::jsonb,'[{"type":"image","