كما هو الحال مع نباتات جلد النمر الأخرى، من السهل جدًا الاعتناء بهذه النباتات العصارية، فهي خبراء في تنقية الهواء، ويمكنها أيضًا تحمل ظروف الإضاءة المنخفضة مما يجعلها واحدة من أفضل النباتات للمبتدئين أو تربية النباتات الخالية من الإجهاد',56.35,'product','{"sourceUrl":"https://xeoufj.zid.store/products/نبته-جلد-النمر","quoteOnly":false,"stock":10,"attributes":[{"label":"رمز المنتج","value":"Z.472517.17031598978443594"},{"label":"السعر قبل التخفيض","value":"78.20 ريال"}],"optionGroups":[{"id":"646822d8-9300-4c5f-9bc4-ca2dd388fc4f","label":"حجم النبتة🌱","type":"select","required":false,"hint":"","minChoices":0,"maxChoices":1,"choices":[{"id":"a4aa8e86-cf60-4b6e-a6e9-44c1554b3755","label":"كبيرة🪴","priceDelta":95}]},{"id":"5dac9303-6be4-48f7-a4c6-dc955ccdbb4c","label":"اختار الأصيص المناسب لك🪴","type":"multi","required":true,"hint":"","minChoices":1,"maxChoices":3,"choices":[{"id":"b51ffa1f-d82b-44a5-8996-9caf581e06fc","label":"اصيص بلاستك","priceDelta":0},{"id":"new-1728216769165","label":"اصيص زجاجي","priceDelta":20},{"id":"new-1764236084992","label":"أصيص سيراميك","priceDelta":30}]}]}'::jsonb,6,true,'4e5a661a-7029-40ec-a3bc-dc75959a05bb/2d542cc4-a896-4785-89d8-fb9bd5406853/together-20261101-87a968ef-311e-4780-9113-f4118f7c6996-f4aae60c1e43.webp','[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/2d542cc4-a896-4785-89d8-fb9bd5406853/together-20261101-7247bcec-58f5-46c6-b50d-eb33509ff3b3-6ac504f6868f.webp","alt":"نبتة جلد النمر"}]'::jsonb,'[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/2d542cc4-a896-4785-89d8-fb9bd5406853/together-20261101-87a968ef-311e-4780-9113-f4118f7c6996-f4aae60c1e43.webp","alt":"نبتة جلد النمر","primary":true},{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/2d542cc4-a896-4785-89d8-fb9bd5406853/together-20261101-7247bcec-58f5-46c6-b50d-eb33509ff3b3-6ac504f6868f.webp","alt":"نبتة جلد النمر","primary":false}]'::jsonb,false);
