INSERT INTO public.menu_products(id,cafe_id,category_id,name,description,price,catalog_kind,commerce_details,sort_order,available,image_storage_path,image_gallery,media,available_for_pickup) VALUES('9a8dbe13-256e-4532-837c-5b86f4c4326a','4e5a661a-7029-40ec-a3bc-dc75959a05bb','05a79390-c810-4e6a-8810-e4102ea7f631','كوب نماء','ما يميز كوب نماء:
• تجربة زراعية متكاملة: يأتي مع كيس تربة عضوية غنية وبذور مختارة بعناية لتضمن لكِ بداية ناجحة.
• تصميم عصري مستدام: يجمع بين دفء الفخار وتغليف "Together Plants" الأنيق، مما يجعله قطعة ديكور بحد ذاته.
• هدية ذات معنى: مثالي ليكون توزيعات في المناسبات، أو هدية تعليمية للأطفال، أو حتى إضافة ملهمة لمكتبك.
• بساطة العناية: مرفق معه خطوات سهلة تجعل من الزراعة نشاطاً ممتعاً ومريحاً للأعصاب.
محتويات المجموعة:
• مركن فخاري يحمل شعارنا الذهبي.
• مغلف تربة معالجة وجاهزة للزراعة.
• بذور (موسمية / عطرية).
• غطاء ورقي أنيق يحمل هويتنا ويحافظ على المحتويات.',14,'product','{"sourceUrl":"https://xeoufj.zid.store/products/كوب-نماء","quoteOnly":false,"stock":50,"attributes":[{"label":"رمز المنتج","value":"Z.17764309054387054"}],"optionGroups":[{"id":"0c2c8aeb-96a9-49ee-8663-194e89e680ef","label":"اختار كمية المناسبة 🪴","type":"multi","required":false,"hint":"","minChoices":0,"maxChoices":2,"choices":[{"id":"4fdedf33-ae47-49c6-b475-4ea5df5e9d77","label":"24 حبة بـ 12 ريال","priceDelta":288},{"id":"new-1776431432394","label":"36 حبة بـ 11 ريال","priceDelta":396}]}]}'::jsonb,55,true,'4e5a661a-7029-40ec-a3bc-dc75959a05bb/9a8dbe13-256e-4532-837c-5b86f4c4326a/together-20261101-31066e91-8402-409a-aed0-512026672b43-3b38d575bd33.webp','[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/9a8dbe13-256e-4532-837c-5b86f4c4326a/together-20261101-ed964100-2069-44b6-8a84-1efd8adaa54f-759f8a4db5dd.webp","alt":"كوب نماء"},{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/9a8dbe13-256e-4532-837c-5b86f4c4326a/together-20261101-6b74f788-43df-4da1-9f2d-e0d3cdf49e44-eb75526c581f.webp","alt":"كوب نماء"}]'::jsonb,'[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/9a8dbe13-256e-4532-837c-5b86f4c4326a/together-20261101-31066e91-8402-409a-aed0-512026672b43-3b38d575bd33.webp","alt":"كوب نماء","primary":true},{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/9a8dbe13-256e-4532-837c-5b86f4c4326a/together-20261101-ed964100-2069-44b6-8a84-1efd8adaa54f-759f8a4db5dd.webp","alt":"كوب نماء","primary":false},{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/9a8dbe13-256e-4532-837c-5b86f4c4326a/together-20261101-6b74f788-43df-4da1-9f2d-e0d3cdf49e44-eb75526c581f.webp","alt":"كوب نماء","primary":false}]'::jsonb,false);
