INSERT INTO public.menu_products(id,cafe_id,category_id,name,description,price,catalog_kind,commerce_details,sort_order,available,image_storage_path,image_gallery,media,available_for_pickup) VALUES('a00f1a5a-8d85-4cd3-8828-ae8f0d403732','4e5a661a-7029-40ec-a3bc-dc75959a05bb','381a444b-ac0e-477e-8076-0ce9e45f922b','نبتة مونستيرا '' كبيرة ''','ستكون هذه النسخة العملاقة من مصنع الجبن السويسري بمثابة قطعة المقاومة في منزلك. تحتوي هذه النباتات الجميلة ذات الحجم الكبير والأوراق الخضراء الداكنة والأوراق اللامعة على الكثير من النوافذ البيضاوية الكبيرة، وستشكل النبات المثالي المتميز في أي مكان بالداخل.
يرجى العلم أن الخيار الأصغر هو نبات أقل نضجًا وسيستغرق وقتًا لزراعة أوراق كبيرة ومُنفَّذة مثل نبات الأصيص الأكبر حجمًا مقاس 24 سم في الصورة. نظرًا لحجم الأوراق ودقتها، غالبًا ما يكون هناك ضرر تجميلي صغير لا يمكن تجنبه لبعض الأوراق، لكنها يمكن أن تنمو أوراقًا جديدة بسرعة كبيرة.',150,'product','{"sourceUrl":"https://xeoufj.zid.store/products/مونستيرا-ديليسيوسا","quoteOnly":false,"stock":10,"attributes":[{"label":"رمز المنتج","value":"Z.472517.17192644980711236"}],"optionGroups":[{"id":"444f2fb0-b4e6-4449-acd2-0c72d7b1bbde","label":"حجم النبتة🌱","type":"select","required":false,"hint":"","minChoices":0,"maxChoices":1,"choices":[{"id":"84d1ff18-dc17-49c6-9336-1794498cb874","label":"كبيرة🪴","priceDelta":90}]},{"id":"96c7be00-3cbf-42dc-a1ee-1a60a6a644b3","label":"اختار الأصيص المناسب لك🪴","type":"multi","required":true,"hint":"","minChoices":1,"maxChoices":3,"choices":[{"id":"f3d7f215-53f1-4ad9-8273-68205ec5ba7a","label":"أصيص بلاستك","priceDelta":0},{"id":"new-1728216923616","label":"أصيص زجاجي","priceDelta":20},{"id":"new-1764236614032","label":"أصيص سيراميك","priceDelta":30}]}]}'::jsonb,71,true,'4e5a661a-7029-40ec-a3bc-dc75959a05bb/a00f1a5a-8d85-4cd3-8828-ae8f0d403732/together-20261101-2d68583c-e806-451a-96c8-b27eaa9889b5-b70a60b39f5d.webp','[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/a00f1a5a-8d85-4cd3-8828-ae8f0d403732/together-20261101-85e33caf-b3b7-4463-9740-dc00cbb262fb-63a4511f498c.webp","alt":"نبتة مونستيرا '' كبيرة ''"}]'::jsonb,'[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/a00f1a5a-8d85-4cd3-8828-ae8f0d403732/together-20261101-2d68583c-e806-451a-96c8-b27eaa9889b5-b70a60b39f5d.webp","alt":"نبتة مونستيرا '' كبيرة ''","primary":true},{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/a00f1a5a-8d85-4cd3-8828-ae8f0d403732/together-20261101-85e33caf-b3b7-4463-9740-dc00cbb262fb-63a4511f498c.webp","alt":"نبتة مونستيرا '' كبيرة ''","primary":false}]'::jsonb,false);
INSERT INTO public.menu_products(id,cafe_id,category_id,name,description,price,catalog_kind,commerce_details,sort_order,available,image_storage_path,image_gallery,media,available_for_pickup) VALUES('f43c99bf-da2d-45ed-87d0-af4bca01470d','4e5a661a-7029-40ec-a3bc-dc75959a05bb','381a444b-ac0e-477e-8076-0ce9e45f922b','صبار ايشيفيريا','هي عصارية في عائلة Crassulaceae الأصلية في المكسيك. يحظى هذا النبات النابض بالحياة بتقدير كبير في نمو الوردة، المزينة بالتصبغ الأخضر المزرق. تكون الألوان أكثر بروزا عند تعرضها لأشعة الشمس المباشرة مما يجعلها مثالية لعتبات النوافذ الصغيرة أو المساحة المشمسة.
ضماننا:🪪
ستصل نباتاتك في حالة سعيدة وصحية مضمونة.
إذا لم يكن الأمر كذلك ، فإننا نستبدلها مجانًا. ما عليك سوى التواصل معنا بصورة في غضون 3 يومًا من استلام طلبك. يتعلم أكثر.',46,'product','{"sourceUrl":"https://xeoufj.zid.store/products/مزيج-عصاري","quoteOnly":false,"stock":10,"attributes":[{"label":"رمز المنتج","value":"Z.472517.17031626566402366"}],"optionGroups":[{"id":"4c6a1618-02d9-4792-b380-543fb07b2c23","label":"اختار الأصيص المناسب لك🪴","type":"multi","required":true,"hint":"","minChoices":1,"maxChoices":3,"choices":[{"id":"14fd72de-982c-4a58-a535-a8b3e7a1006a","label":"أصيص بلاستك","priceDelta":0},{"id":"new-1728216864960","label":"اصيص زحاجي","priceDelta":15},{"id":"new-1764236375293","label":"أصيص سيراميك","priceDelta":35}]}]}'::jsonb,72,true,'4e5a661a-7029-40ec-a3bc-dc75959a05bb/f43c99bf-da2d-45ed-87d0-af4bca01470d/together-20261101-aa993cd5-92a7-46ee-9b6b-76ec3b457917-fa2b9721c1d9.webp','[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/f43c99bf-da2d-45ed-87d0-af4bca01470d/together-20261101-d98f6910-9e31-4b08-a544-84de3793ad0a-8a28261a1bee.webp","alt":"صبار ايشيفيريا"}]'::jsonb,'[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/f43c99bf-da2d-45ed-87d0-af4bca01470d/together-20261101-aa993cd5-92a7-46ee-9b6b-76ec3b457917-fa2b9721c1d9.webp","alt":"صبار ايشيفيريا","primary":true},{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/f43c99bf-da2d-45ed-87d0-af4bca01470d/together-20261101-d98f6910-9e31-4b08-a544-84de3793ad0a-8a28261a1bee.webp","alt":"صبار ايشيفيريا","primary":false}]'::jsonb,false);
