INSERT INTO public.menu_products(id,cafe_id,category_id,name,description,price,catalog_kind,commerce_details,sort_order,available,image_storage_path,image_gallery,media,available_for_pickup) VALUES('ee033a20-0932-4327-82e5-73bc5d0b392a','4e5a661a-7029-40ec-a3bc-dc75959a05bb','381a444b-ac0e-477e-8076-0ce9e45f922b','صبار سنسيفريا','تحتوي النباتات الأفعوانية الأسطوانية على أوراق سميكة ولحمية على شكل رمح. الأوراق ضيقة إلى حد ما وتصدر بيانًا معماريًا في أي غرفة. كما هو الحال مع نباتات الثعابين الأخرى، من السهل جدًا الاعتناء بهذه النباتات العصارية، فهي خبراء في تنقية الهواء، ويمكنها أيضًا تحمل ظروف الإضاءة المنخفضة. مما يجعلها واحدة من أفضل النباتات للمبتدئين أو تربية النباتات الخالية من الإجهاد.',86.25,'product','{"sourceUrl":"https://xeoufj.zid.store/products/صبار-سنسيفريا","quoteOnly":false,"stock":0,"attributes":[{"label":"رمز المنتج","value":"Z.472517.1703162444149808"}],"optionGroups":[{"id":"2b35430b-d9d4-4fd3-845c-5bfd8e3dee7d","label":"حجم نبتة🌱","type":"multi","required":true,"hint":"","minChoices":1,"maxChoices":1,"choices":[{"id":"b0a2c4ff-c01e-4f74-918a-ed62bc287dbd","label":"كبيرة","priceDelta":103}]},{"id":"3362970d-607e-49f9-8c40-66914c0326d7","label":"اختار الأصيص المناسب لك🪴","type":"multi","required":true,"hint":"","minChoices":1,"maxChoices":3,"choices":[{"id":"233a5712-5fff-4db4-9f51-8cb00ac80f51","label":"اصيص بلاستك","priceDelta":0},{"id":"new-1728216819952","label":"اصيص زجاجي","priceDelta":25},{"id":"new-1764235929471","label":"أصيص سيراميك","priceDelta":35}]}]}'::jsonb,87,false,'4e5a661a-7029-40ec-a3bc-dc75959a05bb/ee033a20-0932-4327-82e5-73bc5d0b392a/together-20261101-4548d1ba-1d99-4499-bf57-131d4b39d0c8-b9cb4251e507.webp','[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/ee033a20-0932-4327-82e5-73bc5d0b392a/together-20261101-61f594c6-25fc-4b28-9ba8-aac93a099b26-84601ff3867a.webp","alt":"صبار سنسيفريا"}]'::jsonb,'[{"type":"image","assetId":"4e5a661a-7029-40ec-a3bc-dc75959a05bb/ee033a20-0932-4327-82e5-73bc5d0b392a/together-2026110