DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafes t WHERE id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.menu_products t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.menu_categories t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafe_loyalty_programs t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafe_custom_identity t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.cafe_settings t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.subscriptions t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.brand_feature_overrides t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'store_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text) FROM public.gift_store_settings t WHERE cafe_id<>'4e5a661a-7029-40ec-a3bc-dc75959a05bb'::uuid),'plans',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM public.platform_plans t)) INTO actual;IF actual IS DISTINCT FROM (SELECT snapshot FROM together_before) THEN RAISE EXCEPTION 'Another brand or shared plan changed';END IF;IF (SELECT count(*) FROM public.menu_products WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb')<>88 OR (SELECT count(*) FROM public.menu_products WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb' AND catalog_kind='service')<>12 OR (SELECT count(*) FROM public.menu_products WHERE cafe_id='4e5a661a-7029-40ec-a3bc-dc75959a05bb' AND NOT available)<>15 THEN RAISE EXCEPTION 'Together catalog verification failed';END IF;END $verify$;
COMMIT;
